-- Reviewed Vergalid actor profiles; missing numeric values are labelled approved emulator defaults.
-- Explicit review and numeric rare-chance parameters are required; no percentage is silently chosen.
-- Three quest drops use a minimum-one acquisition bundle, not a recovered original group-drop count.
-- Preserve original spawn2, spawngroup and patrol-grid rows; only add named outcomes to three original groups.
SET NAMES utf8mb4;
SET SESSION check_constraint_checks=1;
DROP TEMPORARY TABLE IF EXISTS `_verga_npc_types`;
CREATE TEMPORARY TABLE `_verga_npc_types` LIKE `npc_types`;
DROP TEMPORARY TABLE IF EXISTS `_verga_loottable`;
CREATE TEMPORARY TABLE `_verga_loottable` LIKE `loottable`;
DROP TEMPORARY TABLE IF EXISTS `_verga_lootdrop`;
CREATE TEMPORARY TABLE `_verga_lootdrop` LIKE `lootdrop`;
DROP TEMPORARY TABLE IF EXISTS `_verga_loottable_entries`;
CREATE TEMPORARY TABLE `_verga_loottable_entries` LIKE `loottable_entries`;
DROP TEMPORARY TABLE IF EXISTS `_verga_lootdrop_entries`;
CREATE TEMPORARY TABLE `_verga_lootdrop_entries` LIKE `lootdrop_entries`;
DROP TEMPORARY TABLE IF EXISTS `_verga_original_spawn2`;
CREATE TEMPORARY TABLE `_verga_original_spawn2` LIKE `spawn2`;
DROP TEMPORARY TABLE IF EXISTS `_verga_original_spawngroup`;
CREATE TEMPORARY TABLE `_verga_original_spawngroup` LIKE `spawngroup`;
DROP TEMPORARY TABLE IF EXISTS `_verga_original_grid`;
CREATE TEMPORARY TABLE `_verga_original_grid` LIKE `grid`;
DROP TEMPORARY TABLE IF EXISTS `_verga_original_grid_entries`;
CREATE TEMPORARY TABLE `_verga_original_grid_entries` LIKE `grid_entries`;
DROP TEMPORARY TABLE IF EXISTS `_verga_guard`;
CREATE TEMPORARY TABLE `_verga_guard`(ok TINYINT NOT NULL CHECK(ok=1))ENGINE=InnoDB;
START TRANSACTION;
SET @vergalid_actor_world_ok=
(COALESCE(@vergalid_world_reviewed,0)=1)
 AND (COALESCE(@vergalid_actor_profiles_reviewed,0)=1)
 AND (@vergalid_skullrend_chance BETWEEN 1 AND 99 AND @vergalid_skullrend_chance=FLOOR(@vergalid_skullrend_chance))
 AND (@vergalid_vuryn_chance BETWEEN 1 AND 99 AND @vergalid_vuryn_chance=FLOOR(@vergalid_vuryn_chance))
 AND (NOT EXISTS(SELECT 1 FROM `npc_types` a WHERE a.`id` IN(404900,404901,404902,404903,404904,404905,404906) AND NOT EXISTS(SELECT 1 FROM `_verga_npc_types` e WHERE a.`id`<=>e.`id` AND BINARY a.`name`<=>BINARY e.`name` AND BINARY a.`lastname`<=>BINARY e.`lastname` AND a.`level`<=>e.`level` AND a.`race`<=>e.`race` AND a.`class`<=>e.`class` AND a.`bodytype`<=>e.`bodytype` AND a.`hp`<=>e.`hp` AND a.`mana`<=>e.`mana` AND a.`gender`<=>e.`gender` AND a.`texture`<=>e.`texture` AND a.`helmtexture`<=>e.`helmtexture` AND a.`herosforgemodel`<=>e.`herosforgemodel` AND a.`size`<=>e.`size` AND a.`hp_regen_rate`<=>e.`hp_regen_rate` AND a.`hp_regen_per_second`<=>e.`hp_regen_per_second` AND a.`mana_regen_rate`<=>e.`mana_regen_rate` AND a.`loottable_id`<=>e.`loottable_id` AND a.`merchant_id`<=>e.`merchant_id` AND a.`greed`<=>e.`greed` AND a.`alt_currency_id`<=>e.`alt_currency_id` AND a.`npc_spells_id`<=>e.`npc_spells_id` AND a.`npc_spells_effects_id`<=>e.`npc_spells_effects_id` AND a.`npc_faction_id`<=>e.`npc_faction_id` AND a.`adventure_template_id`<=>e.`adventure_template_id` AND a.`trap_template`<=>e.`trap_template` AND a.`mindmg`<=>e.`mindmg` AND a.`maxdmg`<=>e.`maxdmg` AND a.`attack_count`<=>e.`attack_count` AND BINARY a.`npcspecialattks`<=>BINARY e.`npcspecialattks` AND BINARY a.`special_abilities`<=>BINARY e.`special_abilities` AND a.`aggroradius`<=>e.`aggroradius` AND a.`assistradius`<=>e.`assistradius` AND a.`face`<=>e.`face` AND a.`luclin_hairstyle`<=>e.`luclin_hairstyle` AND a.`luclin_haircolor`<=>e.`luclin_haircolor` AND a.`luclin_eyecolor`<=>e.`luclin_eyecolor` AND a.`luclin_eyecolor2`<=>e.`luclin_eyecolor2` AND a.`luclin_beardcolor`<=>e.`luclin_beardcolor` AND a.`luclin_beard`<=>e.`luclin_beard` AND a.`drakkin_heritage`<=>e.`drakkin_heritage` AND a.`drakkin_tattoo`<=>e.`drakkin_tattoo` AND a.`drakkin_details`<=>e.`drakkin_details` AND a.`armortint_id`<=>e.`armortint_id` AND a.`armortint_red`<=>e.`armortint_red` AND a.`armortint_green`<=>e.`armortint_green` AND a.`armo