unique_`<=>e.`unique_` AND a.`fixed`<=>e.`fixed` AND a.`ignore_despawn`<=>e.`ignore_despawn` AND a.`show_name`<=>e.`show_name` AND a.`untargetable`<=>e.`untargetable` AND a.`charm_ac`<=>e.`charm_ac` AND a.`charm_min_dmg`<=>e.`charm_min_dmg` AND a.`charm_max_dmg`<=>e.`charm_max_dmg` AND a.`charm_attack_delay`<=>e.`charm_attack_delay` AND a.`charm_accuracy_rating`<=>e.`charm_accuracy_rating` AND a.`charm_avoidance_rating`<=>e.`charm_avoidance_rating` AND a.`charm_atk`<=>e.`charm_atk` AND a.`skip_global_loot`<=>e.`skip_global_loot` AND a.`rare_spawn`<=>e.`rare_spawn` AND a.`stuck_behavior`<=>e.`stuck_behavior` AND a.`model`<=>e.`model` AND a.`flymode`<=>e.`flymode` AND a.`always_aggro`<=>e.`always_aggro` AND a.`exp_mod`<=>e.`exp_mod` AND a.`heroic_strikethrough`<=>e.`heroic_strikethrough` AND a.`faction_amount`<=>e.`faction_amount` AND a.`keeps_sold_items`<=>e.`keeps_sold_items` AND a.`is_parcel_merchant`<=>e.`is_parcel_merchant` AND a.`multiquest_enabled`<=>e.`multiquest_enabled` AND a.`npc_tint_id`<=>e.`npc_tint_id`)))
 AND (NOT EXISTS(SELECT 1 FROM `loottable` a WHERE a.`id` IN(3040803,3040808,3040812) AND NOT EXISTS(SELECT 1 FROM `_verga_loottable` e WHERE a.`id`<=>e.`id` AND BINARY a.`name`<=>BINARY e.`name` AND a.`mincash`<=>e.`mincash` AND a.`maxcash`<=>e.`maxcash` AND a.`avgcoin`<=>e.`avgcoin` AND a.`done`<=>e.`done` AND a.`min_expansion`<=>e.`min_expansion` AND a.`max_expansion`<=>e.`max_expansion` AND a.`content_flags`<=>e.`content_flags` AND a.`content_flags_disabled`<=>e.`content_flags_disabled`)))
 AND (NOT EXISTS(SELECT 1 FROM `lootdrop` a WHERE a.`id` IN(3040803,3040808,3040812) AND NOT EXISTS(SELECT 1 FROM `_verga_lootdrop` e WHERE a.`id`<=>e.`id` AND BINARY a.`name`<=>BINARY e.`name` AND a.`min_expansion`<=>e.`min_expansion` AND a.`max_expansion`<=>e.`max_expansion` AND a.`content_flags`<=>e.`content_flags` AND a.`content_flags_disabled`<=>e.`content_flags_disabled`)))
 AND (NOT EXISTS(SELECT 1 FROM `loottable_entries` a WHERE a.`loottable_id` IN(3040803,3040808,3040812) AND NOT EXISTS(SELECT 1 FROM `_verga_loottable_entries` e WHERE a.`loottable_id`<=>e.`loottable_id` AND a.`lootdrop_id`<=>e.`lootdrop_id` AND a.`multiplier`<=>e.`multiplier` AND a.`droplimit`<=>e.`droplimit` AND a.`mindrop`<=>e.`mindrop` AND a.`probability`<=>e.`probability`)))
 AND (NOT EXISTS(SELECT 1 FROM `lootdrop_entries` a WHERE a.`lootdrop_id` IN(3040803,3040808,3040812) AND NOT EXISTS(SELECT 1 FROM `_verga_lootdrop_entries` e WHERE a.`lootdrop_id`<=>e.`lootdrop_id` AND a.`item_id`<=>e.`item_id` AND a.`item_charges`<=>e.`item_charges` AND a.`equip_item`<=>e.`equip_item` AND a.`chance`<=>e.`chance` AND a.`disabled_chance`<=>e.`disabled_chance` AND a.`trivial_min_level`<=>e.`trivial_min_level` AND a.`trivial_max_level`<=>e.`trivial_max_level` AND a.`multiplier`<=>e.`multiplier` AND a.`npc_min_level`<=>e.`npc_min_level` AND a.`npc_max_level`<=>e.`npc_max_level` AND a.`min_expansion`<=>e.`min_expansion` AND a.`max_expansion`<=>e.`max_expansion` AND a.`content_flags`<=>e.`content_flags` AND a.`content_flags_disabled`<=>e.`content_flags_disabled`)))
 AND ((SELECT COUNT(*) FROM `spawn2` a WHERE a.spawngroupID IN(76486,76494,76526))=3 AND NOT EXISTS(SELECT 1 FROM `spawn2` a WHERE a.spawngroupID IN(76486,76494,76526) AND NOT EXISTS(SELECT 1 FROM `_verga_original_spawn2` e WHERE a.`id`<=>e.`id` AND a.`spawngroupID`<=>e.`spawngroupID` AND BINARY a.`zone`<=>BINARY e.`zone` AND a.`version`<=>e.`version` AND a.`x`<=>e.`x` AND a.`y`<=>e.`y` AND a.`z`<=>e.`z` AND a.`heading`<=>e.`heading` AND a.`respawntime`<=>e.`respawntime` AND a.`variance`<=>e.`variance` AND a.`pathgrid`<=>e.`pathgrid` AND a.`path_when_zone_idle`<=>e.`path_when_zone_idle` AND a.`_condition`<=>e.`_condition` AND a.`cond_value`<=>e.`cond_value` AND a.`animation`<=>e.`animation` AND a.`min_expansion`<=>e.`min_expansion` AND a.`max_expansion`<=>e.`max_expansion` AND a.`content_flags`<=>e.`content_flags` AND a.`content_flags_disabled`<=>e.`content_flags_disabled`)))
 AND ((SELECT COUNT(*) FROM `spawngroup` a WHERE a.id IN(76486,76494,76526))=3 AND NOT EXISTS(SELECT 1 FROM `spawngroup` a WHERE a.id IN(76486,76494,76526) AND NOT EXISTS(SELECT 1 FROM `_verga_original_spawngroup` e WHERE a.`id`<=>e.`id` AND BINARY a.`name`<=>BINARY e.`name` AND a.`spawn_limit`<=>e.`spawn_limit` AND a.`dist`<=>e.`dist` AND a.`max_x`<=>e.`max_x` AND a.`min_x`<=>e.`min_x` AND a.`max_y`<=>e.`max_y` AND a.`min_y`<=>e.`min_y` AND a.`delay`<=>e.`delay` AND a.`mindelay`<=>e.`mindelay` AND a.`despawn`<=>e.`despawn` AND a.`despawn_timer`<=>e.`despawn_timer` AND a.`wp_spawns`<=>e.`wp_spawns`)))
 AND ((SELECT COUNT(*) FROM `grid` a WHERE a.zoneid=404 AND a.id IN(543274,543276))=2 AND NOT EXISTS(SELECT 1 FROM `grid` a WHERE a.zoneid=404 AND a.id IN(543274,543276) AND NOT EXISTS(SELECT 1 FROM `_verga_original_grid` e WHERE a.`id`<=>e.`id` AND a.`zoneid`<=>e.`zoneid` AND a.`type`<=>e.`type` AND a.`type2`<=>e.`type2`)))
 AND ((SELECT COUNT(*) FROM `grid_entries` a WHERE a.zoneid=404 AND a.gridid IN(543274,543276))=8 AND NOT EXISTS(SELECT 1 FROM `grid_entries` a WHERE a.zoneid=404 AND a.gridid IN(543274,543276) AND NOT EXISTS(SELECT 1 FROM `_verga_original_grid_entries` e WHERE a.`gridid`<=>e.`gridid` AND a.`zoneid`<=>e.`zoneid` AND a.`number`<=>e.`number` AND a.`x`<=>e.`x` AND a.`y`<=>e.`y` AND a.`z`<=>e.`z` AND a.`heading`<=>e.`heading` AND a.`pause`<=>e.`pause` AND a.`centerpoint`<=>e.`centerpoint`)))
 AND (EXISTS(SELECT 1 FROM items a WHERE a.id=21488 AND BINARY a.Name=CONVERT(0x53616c69766120436f76657265642048617264656e6564204d6574616c2d416c6c6f79 USING utf8mb4)))
 AND (EXISTS(SELECT 1 FROM items a WHERE a.id=36195 AND BINARY a.Name=CONVERT(0x4b6c617a6167277320416d756c6574 USING utf8mb4)))
 AND (EXISTS(SELECT 1 FROM items a WHERE a.id=36208 AND BINARY a.Name=CONVERT(0x46696c6574206f662056657267616c616b USING utf8mb4)))
 AND (((SELECT COUNT(*) FROM spawnentry a WHERE a.spawngroupID=76486)=1 AND EXISTS(SELECT 1 FROM spawnentry a WHERE a.`spawngroupID`<=>76486 AND a.`npcID`<=>404151 AND a.`chance`<=>100 AND a.`condition_value_filter`<=>1 AND a.`min_time`<=>0 AND a.`max_time`<=>0 AND a.`min_expansion`<=>-1 AND a.`max_expansion`<=>-1 AND a.`content_flags`<=>NULL AND a.`content_flags_disabled`<=>NULL))OR((SELECT COUNT(*) FROM spawnentry a WHERE a.spawngroupID=76486)=2 AND NOT EXISTS(SELECT 1 FROM spawnentry a WHERE a.spawngroupID=76486 AND NOT((a.`spawngroupID`<=>76486 AND a.`npcID`<=>404151 AND a.`chance`<=>100-@vergalid_vuryn_chance AND a.`condition_value_filter`<=>1 AND a.`min_time`<=>0 AND a.`max_time`<=>0 AND a.`min_expansion`<=>-1 AND a.`max_expansion`<=>-1 AND a.`content_flags`<=>NULL AND a.`content_flags_disabled`<=>NULL) OR (a.`spawngroupID`<=>76486 AND a.`npcID`<=>404902 AND a.`chance`<=>@vergalid_vuryn_chance AND a.`condition_value_filter`<=>1 AND a.`min_time`<=>0 AND a.`max_time`<=>0 AND a.`min_expansion`<=>-1 AND a.`max_expansion`<=>-1 AND a.`content_flags`<=>NULL AND a.`content_flags_disabled`<=>NULL)))))
 AND (((SELECT COUNT(*) FROM spawnentry a WHERE a.spawngroupID=76494)=1 AND EXISTS(SELECT 1 FROM spawnentry a WHERE a.`spawngroupID`<=>76494 AND a.`npcID`<=>404154 AND a.`chance`<=>100 AND a.`condition_value_filter`<=>1 AND a.`min_time`<=>0 AND a.`max_time`<=>0 AND a.`min_expansion`<=>-1 AND a.`max_expansion`<=>-1 AND a.`content_flags`<=>NULL AND a.`content_flags_disabled`<=>NULL))OR((SELECT COUNT(*) FROM spawnentry a WHERE a.spawngroupID=76494)=2 AND NOT EXISTS(SELECT 1 FROM spawnentry a WHERE a.spawngroupID=76494 AND NOT((a.`spawngroupID`<=>76494 AND a.`npcID`<=>404154 AND a.`chance`<=>100-@vergalid_skullrend_chance AND a.`condition_value_filter`<=>1 AND a.`min_time`<=>0 AND a.`max_time`<=>0 AND a.`min_expansion`<=>-1 AND a.`max_expansion`<=>-1 AND a.`content_flags`<=>NULL AND a.`content_flags_disabled`<=>NULL) OR (a.`spawngroupID`<=>76494 AND a.`npcID`<=>404901 AND a.`chance`<=>@vergalid_skullrend_chance AND a.`condition_value_filter`<=>1 AND a.`min_time`<=>0 AND a.`max_time`<=>0 AND a.`min_expansion`<=>-1 AND a.`max_expansion`<=>-1 AND a.`content_flags`<=>NULL AND a.`content_flags_disabled`<=>NULL)))))
 AND (((SELECT COUNT(*) FROM spawnentry a WHERE a.spawngroupID=76526)=1 AND EXISTS(SELECT 1 FROM spawnentry a WHERE a.`spawngroupID`<=>76526 AND a.`npcID`<=>404151 AND a.`chance`<=>100 AND a.`condition_value_filter`<=>1 AND a.`min_time`<=>0 AND a.`max_time`<=>0 AND a.`min_expansion`<=>-1 AND a.`max_expansion`<=>-1 AND a.`content_flags`<=>NULL AND a.`content_flags_disabled`<=>NULL))OR((SELECT COUNT(*) FROM spawnentry a WHERE a.spawngroupID=76526)=2 AND NOT EXISTS(SELECT 1 FROM spawnentry a WHERE a.spawngroupID=76526 AND NOT((a.`spawngroupID`<=>76526 AND a.`npcID`<=>404151 AND a.`chance`<=>100-@vergalid_vuryn_chance AND a.`condition_value_filter`<=>1 AND a.`min_time`<=>0 AND a.`max_time`<=>0 AND a.`min_expansion`<=>-1 AND a.`max_expansion`<=>-1 AND a.`content_flags`<=>NULL AND a.`content_flags_disabled`<=>NULL) OR (a.`spawngroupID`<=>76526 AND a.`npcID`<=>404902 AND a.`chance`<=>@vergalid_vuryn_chance AND a.`condition_value_filter`<=>1 AND a.`min_time`<=>0 AND a.`max_time`<=>0 AND a.`min_expansion`<=>-1 AND a.`max_expansion`<=>-1 AND a.`content_flags`<=>NULL AND a.`content_flags_disabled`<=>NULL)))))
 AND ((SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN(CONVERT(0x6e70635f7479706573 USING utf8mb4),CONVERT(0x6c6f6f747461626c65 USING utf8mb4),CONVERT(0x6c6f6f7464726f70 USING utf8mb4),CONVERT(0x6c6f6f747461626c655f656e7472696573 USING utf8mb4),CONVERT(0x6c6f6f7464726f705f656e7472696573 USING utf8mb4),CONVERT(0x737061776e656e747279 USING utf8mb4),CONVERT(0x737061776e32 USING utf8mb4),CONVERT(0x737061776e67726f7570 USING utf8mb4),CONVERT(0x67726964 USING utf8mb4),CONVERT(0x677269645f656e7472696573 USING utf8mb4)) AND ENGINE='InnoDB')=10);
